        BigDecimal ssTax;
        if (gross.compareTo(SS_WEEKLY_CAP) >= 0) {
            ssTax = round2(SS_WEEKLY_CAP.multiply(SS_RATE));
        } else {
            ssTax = round2(gross.multiply(SS_RATE));
        }

