        // RULE-11: rounding applied via round2 throughout.
        // RULE-12: net = gross - federal - state - ss - medicare; floor = 0
        BigDecimal netPay = gross
                .subtract(federalTax)
                .subtract(stateTax)
                .subtract(ssTax)
                .subtract(medicareTax);
        if (netPay.compareTo(ZERO) < 0) {
            netPay = ZERO;
        }

        // ---- EMIT-PIPE-OUTPUT ----------------------------------------
